// ─── DATA TRANSFORMATION ──────────────────────────────────────────────────────

/**
 * batchCert: { certId, certName } | null
 *
 * The trainee API returns ALL certificates the trainee is enrolled in across
 * the whole platform (e.g. BTC + "Principle of Ultrasound"). We only want the
 * one belonging to this batch, so we filter rawData by batchCert.certId first.
 * After that filter, the cert label is simply batchCert.certName — no guessing.
 */
function transformApiData(apiResponse, batchCert = null, batchCertificateIds = [], activityLastScores = []) {
  const { data: rawData = [], reAttempts = [] } = apiResponse;
  const batchCertIds = new Set((batchCert?.certIds || []).filter(Boolean));
  const scopedCertificateIds = new Set((batchCertificateIds || []).filter(Boolean));
  const allowedCertificateIds = batchCertIds.size > 0 ? batchCertIds : scopedCertificateIds;
  const activityScoreMap = new Map(
    (activityLastScores || [])
      .filter(row => row?.resource_id)
      .map(row => [row.resource_id, row])
  );

  // ── Filter to batch certificate only ─────────────────────────────────────
  const data = allowedCertificateIds.size > 0
    ? rawData.filter(item =>
        allowedCertificateIds.has(item.certificate_id) &&
        item.is_hidden !== true &&
        !isRemovedBtcBiometryProbeMindSpark(item)
      )
    : [];

  // ── Re-attempt lookup ─────────────────────────────────────────────────────
  const reAttemptMap = {};
  reAttempts.forEach(ra => {
    if (!ra.resource_id) return;
    if (!reAttemptMap[ra.resource_id]) reAttemptMap[ra.resource_id] = [];
    reAttemptMap[ra.resource_id].push(ra);
  });

  // ── Completion lookup ─────────────────────────────────────────────────────
  const completionMap = {};
  data.forEach(item => {
    if (item.resource_id) completionMap[item.resource_id] = item.is_completed === true;
  });

  // ── Unique certificates ───────────────────────────────────────────────────
  const certOrder = [];
  const certSeen  = new Set();
  data.forEach(item => {
    if (!item.certificate_id || certSeen.has(item.certificate_id)) return;
    certSeen.add(item.certificate_id);
    const rawLabel =
      batchCert?.certById?.[item.certificate_id] ??
      item.certificate_name ??
      item.course_name ??
      item.certificate_id;
    certOrder.push({
      id:    item.certificate_id,
      label: normalizeCertTabLabel(rawLabel, item.certificate_id),
    });
  });

  // ── Modules grouped by certificate ───────────────────────────────────────
  const modulesByCert   = {};
  const resourcesByLMID = {};

  data.forEach(item => {
    const { certificate_id, learning_module_id, unit_name, course_name } = item;

    if (!modulesByCert[certificate_id]) modulesByCert[certificate_id] = new Map();
    const certModules = modulesByCert[certificate_id];

    if (!certModules.has(learning_module_id)) {
      certModules.set(learning_module_id, {
        id: learning_module_id,
        label: unit_name || course_name || learning_module_id,
        locked: false, hasAnyResource: false, done: 0, total: 0,
      });
    }

    if (item.resource_id) certModules.get(learning_module_id).hasAnyResource = true;
    if (!item.resource_id) return;

    if (!resourcesByLMID[learning_module_id]) resourcesByLMID[learning_module_id] = [];
    if (resourcesByLMID[learning_module_id].some(r => r.id === item.resource_id)) return;

    const typeKey          = RESOURCE_TYPE_MAP[item.resource_type] || 'resource';
    const moduleLabel      = normalizeModuleSortLabel(unit_name || course_name || '');
    const resourceName     = (item.resource_name || '').trim();
    const displayResourceName = getDisplayResourceName(moduleLabel, resourceName, item.resource_topic || '');
    const resourceTopic    = getDisplayResourceTopic(moduleLabel, item.resource_topic || '', resourceName);
    const completionSource = typeKey === 'resource'
      ? deriveCompletionSource(displayResourceName, resourceTopic)
      : null;
    const isDone = completionMap[item.resource_id] === true;
    const activityScore = activityScoreMap.get(item.resource_id);
    const isMindSparkResource = isMindSpark(item.resource_name || '');

    const resourceRow = {
      id:               item.resource_id,
      certificateId:    certificate_id,
      learningModuleId: learning_module_id,
      name:             displayResourceName,
      type:             typeKey,
      topic:            resourceTopic,
      displayOrder:     item.display_order ?? null,
      completionSource,
      done:             isDone,
      updatedAt:        item.updated_at || null,
      reAttempts:       reAttemptMap[item.resource_id] || [],
      activityData:     completionSource === 'activity'
        ? {
            attempts: activityScore
              ? Number(activityScore.attempt_count || 1)
              : (isMindSparkResource ? 0 : (isDone ? 1 : 0)),
            correct: activityScore
              ? Number(activityScore.correct_answers || 0)
              : (isMindSparkResource ? 0 : (isDone ? 1 : 0)),
            wrong: activityScore ? Number(activityScore.wrong_answers || 0) : 0,
            total: activityScore
              ? Number(activityScore.total_questions || 0)
              : (isMindSparkResource ? 0 : (isDone ? 1 : 0)),
            scorePercentage: activityScore?.score_percentage !== null && activityScore?.score_percentage !== undefined
              ? Number(activityScore.score_percentage)
              : (isMindSparkResource ? null : (isDone ? 100 : null)),
            sessionDate: activityScore?.session_date || null,
            sessionId: activityScore?.session_id || null,
            resourceId: activityScore?.resource_id || item.resource_id,
            resourceType: activityScore?.resource_type || item.resource_type || null,
            resourceTopic: activityScore?.resource_topic || item.resource_topic || '',
            configuredQuestionCount: Number(activityScore?.configured_question_count || 0),
          }
        : undefined,
    };

    const duplicateResource = resourcesByLMID[learning_module_id].find(r =>
      r.type === resourceRow.type &&
      normalizeSortKey(r.topic) === normalizeSortKey(resourceRow.topic) &&
      normalizeSortKey(r.name) === normalizeSortKey(resourceRow.name)
    );

    if (duplicateResource) {
      duplicateResource.done = duplicateResource.done || resourceRow.done;
      duplicateResource.updatedAt = [duplicateResource.updatedAt, resourceRow.updatedAt].filter(Boolean).sort().pop() || null;
      duplicateResource.reAttempts = [...(duplicateResource.reAttempts || []), ...(resourceRow.reAttempts || [])];
      const resourceAttempts = resourceRow.activityData?.attempts || 0;
      const duplicateAttempts = duplicateResource.activityData?.attempts || 0;
      const resourceSessionDate = Date.parse(resourceRow.activityData?.sessionDate || '') || 0;
      const duplicateSessionDate = Date.parse(duplicateResource.activityData?.sessionDate || '') || 0;
      if (
        resourceAttempts > duplicateAttempts ||
        (resourceAttempts === duplicateAttempts && resourceSessionDate > duplicateSessionDate)
      ) {
        duplicateResource.activityData = resourceRow.activityData;
      }
      return;
    }

    resourcesByLMID[learning_module_id].push(resourceRow);
  });

  // ── Sort modules per certificate ──────────────────────────────────────────
  const modulesByCertFinal = {};
  certOrder.forEach(cert => {
    const modMap = modulesByCert[cert.id];
    if (!modMap) { modulesByCertFinal[cert.id] = []; return; }
    modulesByCertFinal[cert.id] = Array.from(modMap.values())
      .map(mod => ({ ...mod, locked: !mod.hasAnyResource }))
      .sort((a, b) => {
        const ai = MODULE_ORDER.indexOf(normalizeModuleSortLabel(a.label));
        const bi = MODULE_ORDER.indexOf(normalizeModuleSortLabel(b.label));
        return (ai === -1 ? 999 : ai) - (bi === -1 ? 999 : bi);
      });
  });

  // ── Sort resources within each module ────────────────────────────────────
  const sortedResources = {};
  Object.entries(resourcesByLMID).forEach(([lmid, items]) => {
    let unitName = '';
    Object.values(modulesByCertFinal).forEach(mods =>
      mods.forEach(m => { if (m.id === lmid) unitName = m.label; })
    );
    const normalizedUnitName = normalizeModuleSortLabel(unitName);
    sortedResources[lmid] = [...items].sort((a, b) => {
      const aTopicOrder = a.type === 'resource' ? getTopicSortIndex(normalizedUnitName, a.topic) : 999;
      const bTopicOrder = b.type === 'resource' ? getTopicSortIndex(normalizedUnitName, b.topic) : 999;

      if (aTopicOrder !== bTopicOrder) {
        return aTopicOrder - bTopicOrder;
      }

      const pa = a.type === 'resource'
        ? getResourceSortIndex(normalizedUnitName, a.name, a.displayOrder, a.topic)
        : (NON_RESOURCE_ORDER[a.type]?.[normalizeSortKey(a.name)] ?? 999);
      const pb = b.type === 'resource'
        ? getResourceSortIndex(normalizedUnitName, b.name, b.displayOrder, b.topic)
        : (NON_RESOURCE_ORDER[b.type]?.[normalizeSortKey(b.name)] ?? 999);
      return pa - pb;
    });
  });

  // ── Compute done / total counts per module ────────────────────────────────
  Object.values(modulesByCertFinal).forEach(mods => {
    mods.forEach(mod => {
      const res = sortedResources[mod.id] || [];
      mod.total = res.length;
      mod.done  = res.filter(isResourceDone).length;
    });
  });

  return { certs: certOrder, modules: modulesByCertFinal, resources: sortedResources };
}

// ─── SUBMISSION HELPERS ───────────────────────────────────────────────────────

const getConfiguredAnswerKey = answer => String(
  answer?.key ?? answer?.value ?? answer?.answer ?? answer?.option ?? answer?.label ?? ''
);

const normalizeAnswerValue = value => String(value ?? '').trim().toLowerCase();

const getLeadingAnswerToken = value => {
  const normalizedValue = normalizeAnswerValue(value);
  const markerMatch = normalizedValue.match(/^([a-z]|\d{1,3})\s*[-).:]\s*/);
  return markerMatch?.[1] || normalizedValue;
};

const optionMatchesConfiguredKey = (option, answer) => {
  const normalizedAnswer = normalizeAnswerValue(answer);
  if (!normalizedAnswer) return false;

  const answerToken = getLeadingAnswerToken(normalizedAnswer);
  const optionValues = [option?.key, option?.value, option?.label, option?.text]
    .map(normalizeAnswerValue)
    .filter(Boolean);

  return optionValues.some(optionValue =>
    optionValue === normalizedAnswer ||
    getLeadingAnswerToken(optionValue) === answerToken
  );
};

const getConfiguredOptionDetails = (options, key) => {
  return (Array.isArray(options) ? options : []).find(item =>
    optionMatchesConfiguredKey(item, key)
  ) || null;
};

const getConfiguredOptionText = (options, key) => {
  const option = getConfiguredOptionDetails(options, key);
  return option?.text ?? option?.label ?? option?.value ?? '';
};

const groupQuestionsByType = (rows) => {
  const byType = {};
  (Array.isArray(rows) ? rows : []).forEach((row) => {
    const type = row.question_type || 'unknown';
    if (!byType[type]) byType[type] = [];
    byType[type].push(row);
  });
  return byType;
};

const getConfiguredAnswerTimeframe = answer => String(
  answer?.timeframe ?? answer?.expected_timeframe ?? ''
).trim();

const getQuestionMetadataList = (metadata, key) => {
  const value = metadata?.[key];
  if (Array.isArray(value)) return value.filter(Boolean);
  if (typeof value === 'string') {
    return value.split(',').map(item => item.trim()).filter(Boolean);
  }
  return [];
};

function buildImageInterpretationSessions(submissions, questions) {
  const questionRows = Array.isArray(questions)
    ? [...questions].sort((a, b) => Number(a.question_no || 0) - Number(b.question_no || 0))
    : [];

  if ((!Array.isArray(submissions) || submissions.length === 0) && questionRows.length > 0) {
    return [{
      session_id: 'configured-questions',
      created_at: null,
      byType: groupQuestionsByType(questionRows),
      isConfiguredOnly: true,
    }];
  }

  const submissionsBySession = {};
  (Array.isArray(submissions) ? submissions : []).forEach((submission) => {
    const sessionId = submission.session_id || 'unknown';
    if (!submissionsBySession[sessionId]) {
      submissionsBySession[sessionId] = [];
    }
    submissionsBySession[sessionId].push(submission);
  });

  return Object.entries(submissionsBySession)
    .map(([sessionId, sessionRows]) => {
      const latestByQuestion = {};
      sessionRows.forEach((row) => {
        const questionNo = String(row.question_no ?? '');
        const previous = latestByQuestion[questionNo];
        if (!previous || new Date(row.created_at || 0) > new Date(previous.created_at || 0)) {
          latestByQuestion[questionNo] = row;
        }
      });

      const mergedRows = questionRows.length > 0
        ? questionRows.map((question) => ({
            ...question,
            ...latestByQuestion[String(question.question_no ?? '')],
            question_no: question.question_no,
            question_type: question.question_type ?? latestByQuestion[String(question.question_no ?? '')]?.question_type,
            prompt: question.prompt ?? latestByQuestion[String(question.question_no ?? '')]?.prompt ?? '',
            options: Array.isArray(question.options) ? question.options : [],
            correct_answer: question.correct_answer ?? null,
            feedback_correct: question.feedback_correct ?? null,
            feedback_wrong: question.feedback_wrong ?? null,
            assets: Array.isArray(question.assets) ? question.assets : [],
          }))
        : Object.values(latestByQuestion).sort((a, b) => Number(a.question_no || 0) - Number(b.question_no || 0));

      const byType = groupQuestionsByType(mergedRows);

      const latestCreatedAt = sessionRows.reduce((latest, row) => {
        const rowDate = new Date(row.created_at || 0);
        return rowDate > latest ? rowDate : latest;
      }, new Date(0));

      return {
        session_id: sessionId,
        created_at: latestCreatedAt.toISOString(),
        byType,
      };
    })
    .sort((a, b) => new Date(a.created_at) - new Date(b.created_at));
}

function sessionSummary(session) {
  const all = Object.values(session.byType).flat();
  const total = all.length;
  const correct = all.filter(q => q.is_correct === true).length;
  const wrong = all.filter(q => q.is_correct === false).length;
  const answered = correct + wrong;
  const pct = total > 0 ? Math.round((correct / total) * 100) : 0;
  return { total, correct, wrong, answered, pct };
}

// ─── TOPIC GROUPS ─────────────────────────────────────────────────────────────

function buildTopicGroups(items, orderScope = '') {
  const topicMap   = {};
  const directRows = [];
  const scopedTopicOrder = TOPIC_ORDER_BY_MODULE[normalizeSortKey(orderScope)] || TOPIC_ORDER_INDEX;
  const useDisplayOrder = !isMappedOrderScope(orderScope);
  items.forEach(r => {
    if (!r.topic) { directRows.push(r); return; }
    if (!topicMap[r.topic]) topicMap[r.topic] = [];
    topicMap[r.topic].push(r);
  });
  const accordions = Object.entries(topicMap)
    .map(([topic, topicItems]) => ({ topic, items: topicItems }))
    .sort((a, b) => {
      const aDisplayOrder = Math.min(...a.items.map(item => Number(item.displayOrder)).filter(Number.isFinite));
      const bDisplayOrder = Math.min(...b.items.map(item => Number(item.displayOrder)).filter(Number.isFinite));

      if (useDisplayOrder && Number.isFinite(aDisplayOrder) && Number.isFinite(bDisplayOrder) && aDisplayOrder !== bDisplayOrder) {
        return aDisplayOrder - bDisplayOrder;
      }

      const ai = scopedTopicOrder[normalizeSortKey(a.topic)] ?? 999;
      const bi = scopedTopicOrder[normalizeSortKey(b.topic)] ?? 999;
      return (ai === -1 ? 999 : ai) - (bi === -1 ? 999 : bi);
    });
  return { accordions, directRows };
}

// ─── IMAGE INTERPRETATION MODAL ───────────────────────────────────────────────

function QuestionRow({ q }) {
  const answered = q.is_correct === true || q.is_correct === false;
  const right = q.is_correct === true;
  const questionType = String(q.question_type || '');
  const isFindImage = questionType === 'type1';
  const isImageUpload = questionType === 'type2';
  const isAnnotation  = q.question_type === 'annotation1' || q.question_type === 'annotation2';
  const isMeasurement = q.question_type === 'measurement';
  const options = Array.isArray(q.options) ? q.options : [];
  const correctKey = getConfiguredAnswerKey(q.correct_answer);
  const expectedTimeframe = getConfiguredAnswerTimeframe(q.correct_answer) || String(q.metadata?.expected_timeframe ?? '').trim();
  const selectedKey = String(q.option_chosen ?? '');
  const selectedText = getConfiguredOptionText(options, selectedKey);
  const correctText = getConfiguredOptionText(options, correctKey);
  const selectedOption = getConfiguredOptionDetails(options, selectedKey);
  const correctOption = getConfiguredOptionDetails(options, correctKey);
  const expectedLandmarks = getQuestionMetadataList(q.metadata, 'expected_landmarks');

  return (
    <div className={`rounded-xl border bg-white p-3 ${
      right ? 'border-[#8DC63F]/40' : answered ? 'border-red-200' : 'border-gray-200'
    }`}>
      <div className="flex items-start gap-3">
        <div className={`w-7 h-7 rounded-full flex items-center justify-center flex-shrink-0 ${
          right ? 'bg-[#8DC63F]/10 text-[#8DC63F]' : answered ? 'bg-red-50 text-red-500' : 'bg-gray-100 text-gray-400'
        }`}>
          {right ? <CheckCircle2 size={15} /> : answered ? <X size={15} /> : q.question_no}
        </div>
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 mb-1">
            <span className={`text-[10px] font-semibold px-2 py-0.5 rounded-full ${
              right ? 'bg-[#8DC63F]/10 text-[#8DC63F]' : answered ? 'bg-red-50 text-red-500' : 'bg-gray-100 text-gray-400'
            }`}>
              {right ? 'Right' : answered ? 'Wrong' : 'Not answered'}
            </span>
            <span className="text-[10px] text-gray-400">Question {q.question_no}</span>
          </div>

          {q.prompt && (
            <p className="text-sm font-semibold text-gray-800">{q.prompt}</p>
          )}

          {Array.isArray(q.assets) && q.assets.length > 0 && (
            <div className="mt-3 grid grid-cols-1 sm:grid-cols-2 gap-2">
              {q.assets.map((asset, assetIndex) => (
                <div key={assetIndex} className="rounded-lg border border-gray-100 bg-gray-50 overflow-hidden">
                  {asset?.url ? (
                    <img
                      src={asset.url}
                      alt={asset.alt || `Question asset ${assetIndex + 1}`}
                      className="w-full max-h-44 object-contain"
                    />
                  ) : (
                    <div className="p-2 text-[11px] text-gray-500 break-all">{asset?.name || JSON.stringify(asset)}</div>
                  )}
                </div>
              ))}
            </div>
          )}

          {options.length > 0 && (
            <div className="mt-3 grid gap-2">
              {options.map((option, optionIndex) => {
                const optionKey = String(option.key ?? option.value ?? optionIndex + 1);
                const optionText = option.text ?? option.label ?? String(option);
                const optionImageUrl = option.image_url ?? option.imageUrl ?? option.url ?? option.asset_url;
                const selected = answered && optionMatchesConfiguredKey(option, selectedKey);
                const isCorrectOption = optionMatchesConfiguredKey(option, correctKey);

                return (
                  <div
                    key={`${q.question_id || q.question_no}-${optionKey}`}
                    className={`rounded-lg border px-3 py-2 text-xs ${
                      selected
                        ? right
                          ? 'border-[#8DC63F]/50 bg-[#8DC63F]/5'
                          : 'border-red-200 bg-red-50'
                        : isCorrectOption
                          ? 'border-[#8DC63F]/30 bg-[#8DC63F]/5'
                          : 'border-gray-100 bg-gray-50'
                    }`}
                  >
                    <div className="flex items-center justify-between gap-2">
                      <span className="font-medium text-gray-700">
                        <span className="mr-2">{optionKey}.</span>
                        {optionText && optionText !== '[object Object]' ? optionText : ''}
                      </span>
                      <div className="flex gap-1">
                        {selected && <span className="rounded-full bg-gray-900/5 px-2 py-0.5 text-[10px] text-gray-600">Selected</span>}
                        {isCorrectOption && <span className="rounded-full bg-[#8DC63F]/10 px-2 py-0.5 text-[10px] text-[#5d8f20]">Correct</span>}
                      </div>
                    </div>
                    {optionImageUrl && (
                      <div className="mt-2 h-28 rounded-md bg-white overflow-hidden flex items-center justify-center">
                        <img src={optionImageUrl} alt={option.image_alt || optionText || `Option ${optionKey}`} className="h-full w-full object-contain" />
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          )}

          {isFindImage && options.length === 0 && (
            <div className="mt-3 rounded-lg border border-blue-100 bg-blue-50/50 px-3 py-2 text-xs text-blue-600">
              No image options are configured for this Find the Image question.
            </div>
          )}

          <div className="mt-3 space-y-2">
            {isFindImage && (answered || options.length > 0 || correctKey || expectedTimeframe) && (
              <div className="grid gap-2 text-xs">
                <div className="rounded-lg border border-gray-100 bg-gray-50 px-3 py-2">
                  <span className="text-gray-400">Selected: </span>
                  <span className={right ? 'font-semibold text-[#8DC63F]' : answered ? 'font-semibold text-red-500' : 'font-semibold text-gray-500'}>
                    {answered ? (selectedText || selectedOption?.key || q.option_chosen || '—') : '—'}
                  </span>
                </div>
                <div className="rounded-lg border border-gray-100 bg-gray-50 px-3 py-2">
                  <span className="text-gray-400">Correct answer: </span>
                  <span className="font-semibold text-gray-700">
                    {correctText || correctOption?.key || correctKey || expectedTimeframe || '—'}
                  </span>
                </div>
              </div>
            )}
          </div>

          {isImageUpload && (
            <div className="mt-3 rounded-lg border border-indigo-100 bg-indigo-50/50 px-3 py-2 text-xs text-indigo-600">
              This question is answered by uploading an interpreted image.
            </div>
          )}

          {isAnnotation && (
            <div className="mt-3 space-y-2 text-xs">
              {expectedLandmarks.length > 0 && (
                <div className="rounded-lg border border-purple-100 bg-purple-50/50 px-3 py-2 text-purple-600">
                  Expected landmarks: <span className="font-medium">{expectedLandmarks.join(', ')}</span>
                </div>
              )}
              <div className="flex flex-wrap items-center gap-3">
                <span className="text-[#8DC63F] font-medium">Correct labels: {q.correct_label_count ?? 0}</span>
                <span className="text-red-500 font-medium">Wrong labels: {q.wrong_label_count ?? 0}</span>
                <span className="text-gray-400">Unused: {q.unused_label_count ?? 0}</span>
              </div>
            </div>
          )}

          {isMeasurement && (
            <div className="mt-3 flex flex-wrap items-center gap-3 text-xs">
              {q.value != null && (
                <span className="text-gray-600">Value: <span className="font-semibold">{q.value}</span></span>
              )}
              {q.interpretation && (
                <span className={`capitalize font-medium ${q.interpretation === 'good' ? 'text-[#8DC63F]' : 'text-red-500'}`}>
                  Interpretation: {q.interpretation}
                </span>
              )}
              {q.caliper_placement_interpretation && (
                <span className={`capitalize font-medium ${q.caliper_placement_interpretation === 'good' ? 'text-[#8DC63F]' : 'text-amber-500'}`}>
                  Caliper: {q.caliper_placement_interpretation}
                </span>
              )}
            </div>
          )}

          {q.public_url && (
            <a
              href={q.public_url}
              target="_blank"
              rel="noreferrer"
              className="mt-3 inline-flex items-center gap-1 text-[10px] text-blue-500 hover:underline"
            >
              <Eye size={10} /> View submitted image
            </a>
          )}

          {answered && (right ? q.feedback_correct : q.feedback_wrong) && (
            <p className="mt-2 text-xs text-gray-500">{right ? q.feedback_correct : q.feedback_wrong}</p>
          )}
        </div>
      </div>
    </div>
  );
}

function SessionCard({ session, attemptNo, isLatest }) {
  const { total, correct, pct } = sessionSummary(session);
  const sm    = scoreMeta(pct);
  const [open, setOpen] = React.useState(isLatest);
  const types = Object.keys(session.byType);
  const configuredOnly = session.isConfiguredOnly === true;

  return (
    <div className={`border rounded-xl overflow-hidden ${isLatest ? 'border-[#8DC63F]/40' : 'border-gray-200'}`}>
      <button
        onClick={() => setOpen(p => !p)}
        className={`w-full flex items-center gap-3 px-4 py-3 text-left transition-colors
          ${open ? 'bg-gray-50' : 'bg-white hover:bg-gray-50'}`}
      >
        <div className={`w-8 h-8 rounded-full flex items-center justify-center flex-shrink-0 font-bold text-sm
          ${isLatest ? 'bg-[#8DC63F] text-white' : 'bg-gray-100 text-gray-500'}`}>
          {configuredOnly ? <FileText size={15} /> : attemptNo}
        </div>
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2">
            <span className="text-sm font-semibold text-gray-700">
              {configuredOnly ? 'Configured Questions' : attemptNo === 1 ? 'First Attempt' : `Re-attempt ${attemptNo - 1}`}
            </span>
            {isLatest && !configuredOnly && (
              <span className="text-[10px] font-semibold px-2 py-0.5 rounded-full bg-[#8DC63F]/15 text-[#8DC63F]">Latest</span>
            )}
          </div>
          <p className="text-[11px] text-gray-400 mt-0.5">
            {configuredOnly
              ? `${total} configured question${total !== 1 ? 's' : ''} · ${types.length} question type${types.length > 1 ? 's' : ''}`
              : `${formatDateTime(session.created_at)} · ${types.length} question type${types.length > 1 ? 's' : ''}`}
          </p>
        </div>
        {!configuredOnly && (
          <div className="text-right flex-shrink-0 mr-2">
            <p className={`text-lg font-bold leading-none ${sm.cls}`}>
              {correct}<span className="text-sm font-normal text-gray-400">/{total}</span>
            </p>
            <p className={`text-[11px] font-semibold ${sm.cls}`}>{pct}%</p>
          </div>
        )}
        {!configuredOnly && (
          <div className="w-16 flex-shrink-0">
            <div className="w-full bg-gray-100 rounded-full h-1.5">
              <div className="h-1.5 rounded-full transition-all" style={{ width: `${pct}%`, backgroundColor: sm.hex }} />
            </div>
          </div>
        )}
        <ChevronDown size={15} className={`flex-shrink-0 transition-transform ${open ? 'rotate-180 text-[#8DC63F]' : 'text-gray-300'}`} />
      </button>

      {open && (
        <div className="px-4 pb-4 pt-2 space-y-4 bg-white border-t border-gray-100">
          {types.map(type => {
            const qs          = session.byType[type].slice().sort((a, b) => a.question_no - b.question_no);
            const typeCorrect = qs.filter(q => q.is_correct).length;
            const tm          = QUESTION_TYPE_META[type] || { label: type, color: 'bg-gray-100 text-gray-600 border-gray-200' };
            return (
              <div key={type}>
                <div className="flex items-center gap-2 mb-2">
                  <span className={`text-[10px] font-semibold px-2 py-0.5 rounded-full border ${tm.color}`}>{tm.label}</span>
                  <span className="text-[11px] text-gray-400">
                    {configuredOnly ? `${qs.length} question${qs.length !== 1 ? 's' : ''}` : `${typeCorrect}/${qs.length} correct`}
                  </span>
                </div>
                <div className="space-y-1.5">
                  {qs.map(q => <QuestionRow key={q.id || q.question_id || `${type}-${q.question_no}`} q={q} />)}
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

function ImageInterpretModal({ r, token, onClose }) {
  const [loading,  setLoading]  = React.useState(true);
  const [error,    setError]    = React.useState(null);
  const [sessions, setSessions] = React.useState([]);

  React.useEffect(() => {
    let active = true;
    setLoading(true);
    setError(null);

    Promise.all([
      fetchSubmissions(r.id, token),
      fetchMindSparkQuestions(r.id, token),
    ])
      .then(([submissionData, questionData]) => {
        if (!active) return;
        setSessions(buildImageInterpretationSessions(submissionData, questionData));
      })
      .catch(err => {
        if (active) setError(err.message);
      })
      .finally(() => {
        if (active) setLoading(false);
      });

    return () => {
      active = false;
    };
  }, [r.id, token]);

  const attemptSessions = sessions.filter(session => !session.isConfiguredOnly);
  const configuredQuestionCount = sessions
    .filter(session => session.isConfiguredOnly)
    .reduce((sum, sess) => sum + Object.values(sess.byType).flat().length, 0);
  const latest    = attemptSessions[attemptSessions.length - 1] || null;
  const latestSum = latest ? sessionSummary(latest) : null;
  const latestSm  = latestSum ? scoreMeta(latestSum.pct) : null;
  const totalSubs = attemptSessions.reduce((s, sess) => s + Object.values(sess.byType).flat().length, 0);

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 backdrop-blur-sm p-4"
      onClick={e => e.target === e.currentTarget && onClose()}
    >
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-2xl max-h-[85vh] flex flex-col overflow-hidden">
        <div className="flex items-center gap-3 px-5 py-4 border-b border-gray-100 flex-shrink-0">
          <div className="w-9 h-9 rounded-lg bg-purple-50 border border-purple-200 flex items-center justify-center flex-shrink-0">
            <Eye size={16} className="text-purple-500" />
          </div>
          <div className="flex-1 min-w-0">
            <h2 className="text-sm font-bold text-gray-800 truncate">{r.name}</h2>
            <p className="text-[11px] text-gray-400 mt-0.5">
              Image Interpretation · {attemptSessions.length > 0
                ? `${attemptSessions.length} attempt${attemptSessions.length !== 1 ? 's' : ''}`
                : configuredQuestionCount > 0
                  ? `${configuredQuestionCount} configured question${configuredQuestionCount !== 1 ? 's' : ''}`
                  : '0 attempts'}
            </p>
          </div>
          {latestSum && latestSm && (
            <div className="text-center mr-2 flex-shrink-0">
              <p className={`text-xl font-bold leading-none ${latestSm.cls}`}>
                {latestSum.correct}<span className="text-sm font-normal text-gray-400">/{latestSum.total}</span>
              </p>
              <p className={`text-[10px] font-semibold ${latestSm.cls}`}>Latest</p>
            </div>
          )}
          <button
            onClick={onClose}
            className="w-8 h-8 rounded-lg flex items-center justify-center hover:bg-gray-100 transition-colors flex-shrink-0"
          >
            <X size={16} className="text-gray-400" />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto px-5 py-4 space-y-3">
          {loading && (
            <div className="flex items-center justify-center py-16 text-gray-400">
              <Loader2 size={24} className="animate-spin mr-2" />
              <span className="text-sm">Loading submissions…</span>
            </div>
          )}
          {error && !loading && (
            <div className="flex flex-col items-center justify-center py-16 text-red-400">
              <p className="text-sm font-medium">Failed to load submissions</p>
              <p className="text-xs mt-1 text-gray-400">{error}</p>
            </div>
          )}
          {!loading && !error && sessions.length === 0 && (
            <div className="flex flex-col items-center justify-center py-16 text-gray-400">
              <Eye size={32} className="mb-3 text-gray-300" />
              <p className="text-sm font-medium">No submissions yet</p>
              <p className="text-xs mt-1">This resource hasn't been attempted</p>
            </div>
          )}
          {!loading && !error && sessions.map((session, idx) => (
            <SessionCard
              key={session.session_id}
              session={session}
              attemptNo={session.isConfiguredOnly ? 0 : idx + 1}
              isLatest={idx === sessions.length - 1}
            />
          ))}
        </div>

        {!loading && sessions.length > 0 && (
          <div className="flex items-center justify-between px-5 py-3 border-t border-gray-100 bg-gray-50 flex-shrink-0">
            <span className="text-xs text-gray-400">
              {attemptSessions.length > 0
                ? `${attemptSessions.length} session${attemptSessions.length !== 1 ? 's' : ''} · ${totalSubs} total submissions`
                : `${configuredQuestionCount} question${configuredQuestionCount !== 1 ? 's' : ''} configured`}
            </span>
            <button
              onClick={onClose}
              className="px-4 py-1.5 rounded-lg border border-gray-200 hover:border-[#8DC63F] hover:text-[#8DC63F] transition-colors text-xs font-medium text-gray-500"
            >
              Close
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

// ─── PRACTICE EXPANDED PANEL ──────────────────────────────────────────────────

const formatAttemptValue = (value, decimals = 2) => {
  if (value === null || value === undefined || value === '') return '—';
  const num = Number(value);
  if (Number.isFinite(num)) return Number.isInteger(num) ? String(num) : num.toFixed(decimals);
  return String(value);
};

const parsePractice12ResultList = (rawResults) => {
  let results = rawResults;

  if (typeof results === 'string') {
    try {
      results = JSON.parse(results);
    } catch {
      results = [];
    }
  }

  if (!Array.isArray(results)) return [];

  return results
    .map((item, idx) => ({
      index: item?.index ?? idx + 1,
      time: Number(item?.time ?? item?.Time ?? 0),
    }))
    .filter(item => Number.isFinite(item.time) && item.time >= 0)
    .sort((a, b) => Number(a.index) - Number(b.index));
};

function Practice12VisualizationPanel({ r, token }) {
  const [loading, setLoading] = React.useState(true);
  const [error, setError] = React.useState(null);
  const [rows, setRows] = React.useState([]);

  React.useEffect(() => {
    let active = true;
    setLoading(true);
    setError(null);

    fetchPractice12Results(r.id, token)
      .then(data => {
        if (active) setRows(data);
      })
      .catch(err => {
        if (active) setError(err.message);
      })
      .finally(() => {
        if (active) setLoading(false);
      });

    return () => {
      active = false;
    };
  }, [r.id, token]);

  if (loading) {
    return (
      <div className="flex items-center justify-center py-10 text-gray-400">
        <Loader2 size={18} className="animate-spin mr-2" />
        <span className="text-sm">Loading practice data...</span>
      </div>
    );
  }

  if (error) {
    return (
      <div className="flex flex-col items-center justify-center py-10 text-red-400">
        <p className="text-sm font-medium">Failed to load practice data</p>
        <p className="text-xs mt-1 text-gray-400">{error}</p>
      </div>
    );
  }

  const latest = rows[0] || null;
  const points = parsePractice12ResultList(latest?.results);

  if (points.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-10 text-gray-400">
        <Target size={28} className="mb-2 text-gray-300" />
        <p className="text-sm font-medium">No practice data found</p>
        <p className="text-xs mt-1">This resource has no saved timing data yet</p>
      </div>
    );
  }

  const totalTime = points.reduce((sum, item) => sum + item.time, 0);
  const averageTime = totalTime / points.length;
  const fastest = Math.min(...points.map(item => item.time));
  const slowest = Math.max(...points.map(item => item.time));
  const maxTime = Math.max(slowest, 1);

  return (
    <div className="space-y-3">
      <div className="grid grid-cols-2 md:grid-cols-4 gap-2">
        {[
          ['Steps', points.length],
          ['Total Time', `${formatAttemptValue(totalTime)} s`],
          ['Average', `${formatAttemptValue(averageTime)} s`],
          ['Fastest', `${formatAttemptValue(fastest)} s`],
        ].map(([label, value]) => (
          <div key={label} className="rounded-lg border border-gray-100 bg-white px-3 py-2">
            <p className="text-[10px] text-gray-400">{label}</p>
            <p className="text-sm font-semibold text-gray-700">{value}</p>
          </div>
        ))}
      </div>

      <div className="rounded-xl border border-gray-100 bg-white p-3">
        <div className="flex items-center justify-between gap-3 mb-3">
          <div className="flex items-center gap-2">
            <Target size={13} className="text-[#8DC63F]" />
            <span className="text-xs font-semibold text-gray-600">Time by step</span>
          </div>
          <span className="text-[10px] text-gray-400">
            Practice {latest?.practice_number || getPracticeNumber(r.name) || ''}
          </span>
        </div>

        <div className="space-y-2.5">
          {points.map(point => {
            const width = `${Math.max(5, Math.round((point.time / maxTime) * 100))}%`;
            return (
              <div key={point.index} className="grid grid-cols-[64px_1fr_58px] items-center gap-2 text-xs">
                <span className="text-gray-500 font-medium">Step {point.index}</span>
                <div className="h-3 rounded-full bg-gray-100 overflow-hidden">
                  <div className="h-full rounded-full bg-[#8DC63F]" style={{ width }} />
                </div>
                <span className="text-right font-semibold text-gray-700">{formatAttemptValue(point.time)} s</span>
              </div>
            );
          })}
        </div>
      </div>

      <div className="rounded-xl border border-blue-100 bg-blue-50/40 px-3 py-3">
        <div className="grid grid-cols-2 gap-2 text-xs text-gray-600">
          <p>Slowest: <span className="font-semibold text-gray-700">{formatAttemptValue(slowest)} s</span></p>
          <p>Resource: <span className="font-semibold text-gray-700">{r.name}</span></p>
        </div>
      </div>
    </div>
  );
}

